export const GetDashboardSummaryResponse = zod.object({
  "projects": zod.int(),
  "voices": zod.int(),
  "scripts": zod.int(),
  "assets": zod.int(),
  "activeJobs": zod.int(),
  "recentJobs": zod.array(zod.object({
  "id": zod.uuid(),
  "type": zod.enum(['extract_audio', 'transcribe', 'create_voice', 'voice_preview', 'generate_voiceover', 'generate_broll', 'assemble', 'deliver']),
  "status": zod.enum(['queued', 'running', 'done', 'failed', 'canceled']),
  "progress": zod.int().min(getDashboardSummaryResponseRecentJobsItemProgressMin).max(getDashboardSummaryResponseRecentJobsItemProgressMax),
  "message": zod.string().nullish().describe('Current step description while running.'),
  "error": zod.string().nullish().describe('Failure reason when status is `failed`.'),
  "projectId": zod.uuid().nullish(),
  "voiceId": zod.uuid().nullish(),
  "outputAssetId": zod.uuid().nullish().describe('Asset produced by the job, when it has finished.'),
  "dependsOnJobId": zod.uuid().nullish().describe('Job that must succeed before this one starts.'),
  "createdAt": zod.coerce.date(),
  "startedAt": zod.coerce.date().nullish(),
  "finishedAt": zod.coerce.date().nullish()
}))
})


/**
 * @summary Get provider configuration status
 */
export const GetSettingsStatusResponse = zod.object({
  "voice": zod.object({
  "configured": zod.boolean(),
  "detail": zod.string().nullish().describe('Extra info, e.g. provider name or error.'),
  "credit": zod.number().nullish().describe('Remaining account credit, when the provider reports it.')
}),
  "broll": zod.object({
  "configured": zod.boolean(),
  "detail": zod.string().nullish().describe('Extra info, e.g. provider name or error.'),
  "credit": zod.number().nullish().describe('Remaining account credit, when the provider reports it.')
}),
  "ftp": zod.object({
  "configured": zod.boolean(),
  "detail": zod.string().nullish().describe('Extra info, e.g. provider name or error.'),
  "credit": zod.number().nullish().describe('Remaining account credit, when the provider reports it.')
})
})


